30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "title")
42	    private String title;
43	
44	    @Column(name = "address")
45	    @NotEmpty
46	    private String address;
47	
48	    @Column(name = "address_line1")
49	    private String addressLine1;
50	
51	    @Column(name = "address_line2")
52	    private String addressLine2;
53	
54	    @Column(name = "city")
55	    @NotEmpty
56	    private String city;
57	
58	    @Column(name = "postcode")
59	    @Pattern(regexp = "^[0-9]{4}$", message = "Postcode must be 4 digits")
60	    private String postcode;
61	
62	    @Column(name = "telephone")
63	    @NotEmpty
64	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
65	    private String telephone;
66	
67	    @Column(name = "email")
68	    private String email;
69	
70	    @Column(name = "registration_date")
71	    private LocalDate registrationDate;
72	
73	    @Column(name = "birth_date")
74	    private LocalDate birthDate;
75	
76	    @Column(name = "customer_code")
77	    private String customerCode;
78	
79	    @Column(name = "household_id")
80	    private String householdId;
81	
82	    @Column(name = "identity_key")
83	    private String identityKey;
84	
85	    @Column(name = "namesake_count")
86	    private Integer namesakeCount;
87	
88	    @Column(name = "household_member_count")
89	    private Integer householdMemberCount;
90	
91	    @Column(name = "membership_number")
92	    private String membershipNumber;
93	
94	    @Column(name = "membership_level_cap")
95	    private Integer membershipLevelCap;
96	
97	    @Column(name = "possible_duplicate")
98	    private Boolean possibleDuplicate;
99	
100	    @Column(name = "possible_duplicate_of")
101	    private Integer possibleDuplicateOf;
102	
103	    @Column(name = "deleted", nullable = false)
104	    private boolean deleted;
105	
106	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
107	    private Set<Pet> pets;
108	
109	    public String getTitle() {
110	        return this.title;
111	    }
112	
113	    public void setTitle(String title) {
114	        this.title = title;
115	    }
116	
117	    /**
118	     * The owner's salutation, derived on read: the {@link #getTitle() title} and last name separated
119	     * by a single space (e.g. {@code "DR who"}) when a title is present, or just the last name when no
120	     * title was supplied.
121	     */
122	    @Transient
123	    public String getSalutation() {
124	        if (this.title != null && !this.title.isBlank()) {
125	            return this.title + " " + getLastName();
126	        }
127	        return getLastName();
128	    }
129	
130	    public String getAddress() {
131	        return this.address;
132	    }
133	
134	    public void setAddress(String address) {
135	        this.address = address;
136	    }
137	
138	    public String getAddressLine1() {
139	        return this.addressLine1;
140	    }
141	
142	    public void setAddressLine1(String addressLine1) {
143	        this.addressLine1 = addressLine1;
144	    }
145	
146	    public String getAddressLine2() {
147	        return this.addressLine2;
148	    }
149	
150	    public void setAddressLine2(String addressLine2) {
151	        this.addressLine2 = addressLine2;
152	    }
153	
154	    public String getCity() {
155	        return this.city;
156	    }
157	
158	    public void setCity(String city) {
159	        this.city = city;
160	    }
161	
162	    public String getPostcode() {
163	        return this.postcode;
164	    }
165	
166	    public void setPostcode(String postcode) {
167	        this.postcode = postcode;
168	    }
169	
170	    public String getTelephone() {
171	        return this.telephone;
172	    }
173	
174	    public void setTelephone(String telephone) {
175	        this.telephone = telephone;
176	    }
177	
178	    public String getEmail() {
179	        return this.email;
180	    }
181	
182	    public void setEmail(String email) {
183	        this.email = email;
184	    }
185	
186	    public LocalDate getRegistrationDate() {
187	        return this.registrationDate;
188	    }
189	
190	    public void setRegistrationDate(LocalDate registrationDate) {
191	        this.registrationDate = registrationDate;
192	    }
193	
194	    public LocalDate getBirthDate() {
195	        return this.birthDate;
196	    }
197	
198	    public void setBirthDate(LocalDate birthDate) {
199	        this.birthDate = birthDate;
200	    }
201	
202	    public String getCustomerCode() {
203	        return this.customerCode;
204	    }
205	
206	    public void setCustomerCode(String customerCode) {
207	        this.customerCode = customerCode;
208	    }
209	
210	    public String getHouseholdId() {
211	        return this.householdId;
212	    }
213	
214	    public void setHouseholdId(String householdId) {
215	        this.householdId = householdId;
216	    }
217	
218	    public String getIdentityKey() {
219	        return this.identityKey;
220	    }
221	
222	    public void setIdentityKey(String identityKey) {
223	        this.identityKey = identityKey;
224	    }
225	
226	    public Integer getNamesakeCount() {
227	        return this.namesakeCount;
228	    }
229	
230	    public void setNamesakeCount(Integer namesakeCount) {
231	        this.namesakeCount = namesakeCount;
232	    }
233	
234	    public Integer getHouseholdMemberCount() {
235	        return this.householdMemberCount;
236	    }
237	
238	    public void setHouseholdMemberCount(Integer householdMemberCount) {
239	        this.householdMemberCount = householdMemberCount;
240	    }
241	
242	    public String getMembershipNumber() {
243	        return this.membershipNumber;
244	    }
245	
246	    public void setMembershipNumber(String membershipNumber) {
247	        this.membershipNumber = membershipNumber;
248	    }
249	
250	    /**
251	     * This owner's membership level ceiling: the derived {@link #getMembershipLevel() membership level}
252	     * is never reported above it. Assigned once when the owner is registered and stored; {@code null}
253	     * when no ceiling applies.
254	     */
255	    public Integer getMembershipLevelCap() {
256	        return this.membershipLevelCap;
257	    }
258	
259	    public void setMembershipLevelCap(Integer membershipLevelCap) {
260	        this.membershipLevelCap = membershipLevelCap;
261	    }
262	
263	    public Boolean getPossibleDuplicate() {
264	        return this.possibleDuplicate;
265	    }
266	
267	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
268	        this.possibleDuplicate = possibleDuplicate;
269	    }
270	
271	    public Integer getPossibleDuplicateOf() {
272	        return this.possibleDuplicateOf;
273	    }
274	
275	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
276	        this.possibleDuplicateOf = possibleDuplicateOf;
277	    }
278	
279	    /**
280	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; the delete
281	     * endpoint flags this true and retains the row rather than removing it. Deleted owners are
282	     * ignored by the create endpoint's duplicate and identity checks.
283	     */
284	    public boolean isDeleted() {
285	        return this.deleted;
286	    }
287	
288	    public void setDeleted(boolean deleted) {
289	        this.deleted = deleted;
290	    }
291	
292	    /**
293	     * The owner's membership points, derived on read: they start at 0, add 2 when an email is
294	     * present, add 1 when {@link #namesakeCount} is 0, add 2 for a household of 3 or more
295	     * ({@link #householdMemberCount}), and add 3 for tenure over one fiscal year (elapsed fiscal
296	     * years from {@link #registrationDate} to today; see {@link #hasTenureBonus(LocalDate)}).
297	     */
298	    @Transient
299	    public Integer getMembershipPoints() {
300	        return membershipPoints(this.email, this.namesakeCount, this.householdMemberCount,
301	            this.registrationDate);
302	    }
303	
304	    /**
305	     * The owner's numeric membership level, derived on read from {@link #getMembershipPoints()}:
306	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more; then held down to the owner's
307	     * {@link #getMembershipLevelCap() membership level cap} when one has been assigned.
308	     */
309	    @Transient
310	    public Integer getMembershipLevel() {
311	        return capMembershipLevel(membershipLevel(getMembershipPoints()), this.membershipLevelCap);
312	    }
313	
314	    /** The membership points derived from the given factors: they start at 0, add 2 when
315	     *  {@code email} is present, add 1 when {@code namesakeCount} is 0, add 2 for a household of 3 or
316	     *  more ({@code householdMemberCount}), and add 3 for sufficient tenure (see
317	     *  {@link #hasTenureBonus(LocalDate)}). */
318	    private static int membershipPoints(String email, Integer namesakeCount,
319	            Integer householdMemberCount, LocalDate registrationDate) {
320	        int points = 0;
321	        if (email != null && !email.isBlank()) {
322	            points += 2;
323	        }
324	        if (namesakeCount != null && namesakeCount == 0) {
325	            points += 1;
326	        }
327	        if (householdMemberCount != null && householdMemberCount >= 3) {
328	            points += 2;
329	        }
330	        if (hasTenureBonus(registrationDate)) {
331	            points += 3;
332	        }
333	        return points;
334	    }
335	
336	    /** Whether the owner's tenure earns the membership tenure bonus: the elapsed fiscal years from
337	     *  {@code registrationDate} to today exceed one, i.e. the registration falls two or more fiscal
338	     *  years before the current one (fiscal years start 1 July). A null registration date earns no
339	     *  bonus. */
340	    private static boolean hasTenureBonus(LocalDate registrationDate) {
341	        return registrationDate != null
342	            && fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) > 1;
343	    }
344	
345	    /**
346	     * The fiscal year (starting 1 July) that contains {@code date}, identified by the calendar year
347	     * in which that fiscal year ends: a date in July-December belongs to the fiscal year ending the
348	     * following calendar year, and a date in January-June to the fiscal year ending that same year
349	     * (e.g. 2026-09-05 -> 2027, 2026-03-01 -> 2026).
350	     */
351	    public static int fiscalYear(LocalDate date) {
352	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
353	    }
354	
355	    /**
356	     * The owner's fiscal year, derived on read from the (business-day-adjusted)
357	     * {@link #registrationDate} as {@code "FY<YY>"}, where YY is the last two digits of the fiscal
358	     * year (starting 1 July) that contains the registration date (e.g. a date of 2026-09-05 yields
359	     * {@code "FY27"}). Returns {@code null} when no registration date is available.
360	     */
361	    @Transient
362	    public String getFiscalYear() {
363	        if (this.registrationDate == null) {
364	            return null;
365	        }
366	        return String.format("FY%02d", fiscalYear(this.registrationDate) % 100);
367	    }
368	
369	    /** The numeric membership level (1-4) mapped from membership points: 1 for 0-1 points, 2 for
370	     *  2-3, 3 for 4-5, and 4 for 6 or more. */
371	    private static int membershipLevel(int points) {
372	        if (points >= 6) {
373	            return 4;
374	        }
375	        if (points >= 4) {
376	            return 3;
377	        }
378	        if (points >= 2) {
379	            return 2;
380	        }
381	        return 1;
382	    }
383	
384	    /** The membership {@code level} held down to {@code cap}, i.e. the smaller of the two, when a cap
385	     *  is present; the level unchanged when {@code cap} is {@code null} and no ceiling applies. */
386	    private static int capMembershipLevel(int level, Integer cap) {
387	        return cap == null ? level : Math.min(level, cap);
388	    }
389	
390	    /**
391	     * The owner's preferred contact channel, derived on read: {@code "EMAIL"} when an email is
392	     * present, otherwise {@code "PHONE"}.
393	     */
394	    @Transient
395	    public String getContactPreference() {
396	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
397	    }
398	
399	    /**
400	     * The owner's age band, derived on read from the {@link #birthDate} relative to the
401	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and
402	     * {@code "SENIOR"} at 65 or over. Returns {@code null} when no birth date (or no registration
403	     * date to measure against) is available.
404	     */
405	    @Transient
406	    public String getAgeBand() {
407	        if (this.birthDate == null || this.registrationDate == null) {
408	            return null;
409	        }
410	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
411	        if (age < 18) {
412	            return "MINOR";
413	        }
414	        if (age < 65) {
415	            return "ADULT";
416	        }
417	        return "SENIOR";
418	    }
419	
420	    /**
421	     * The single Luhn check digit (0-9) computed over the decimal digits contained in the
422	     * {@link #customerCode}, derived on read.
423	     */
424	    @Transient
425	    public Integer getCheckDigit() {
426	        return luhnCheckDigit(this.customerCode);
427	    }
428	
429	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
430	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
431	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
432	        "NSW", new int[] {2000, 2099},
433	        "VIC", new int[] {3000, 3099},
434	        "QLD", new int[] {4000, 4099});
435	
436	    /**
437	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
438	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
439	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
440	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
441	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
442	     */
443	    @Transient
444	    public String getRegion() {
445	        String byPostcode = regionForPostcode(this.postcode);
446	        if (byPostcode != null) {
447	            return byPostcode;
448	        }
449	        if ("Sydney".equals(this.city)) {
450	            return "NSW";
451	        }
452	        if ("Melbourne".equals(this.city)) {
453	            return "VIC";
454	        }
455	        if ("Brisbane".equals(this.city)) {
456	            return "QLD";
457	        }
458	        return "UNKNOWN";
459	    }
460	
461	    /**
462	     * The owner's locality, derived on read from the region-and-hash {@link #getCustomerCode()
463	     * customer code}: the region segment before the first '-' of the customer code
464	     * ('<REGION>-<HASH8>'). Falls back to the owner's {@link #getRegion() region} when no customer
465	     * code has been assigned yet.
466	     */
467	    @Transient
468	    public String getLocality() {
469	        if (this.customerCode != null) {
470	            int dash = this.customerCode.indexOf('-');
471	            if (dash > 0) {
472	                return this.customerCode.substring(0, dash);
473	            }
474	        }
475	        return getRegion();
476	    }
477	
478	    /** Region -> IANA timezone name, the fixed region-to-timezone table ({@code NSW ->
479	     *  Australia/Sydney}, {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
480	    private static final Map<String, String> REGION_TIMEZONES = Map.of(
481	        "NSW", "Australia/Sydney",
482	        "VIC", "Australia/Melbourne",
483	        "QLD", "Australia/Brisbane");
484	
485	    /**
486	     * The owner's timezone, derived on read as the IANA name for the owner's
487	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table
488	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
489	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region carries no entry in
490	     * the table (e.g. {@code UNKNOWN}).
491	     */
492	    @Transient
493	    public String getTimezone() {
494	        return timezoneForRegion(getLocality());
495	    }
496	
497	    /** The IANA timezone name for {@code region} via the fixed region-to-timezone table, or
498	     *  {@code null} when the region carries no entry ({@code NSW -> Australia/Sydney},
499	     *  {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
500	    public static String timezoneForRegion(String region) {
501	        return REGION_TIMEZONES.get(region);
502	    }
503	
504	    /** The inclusive 4-digit postcode {@code {low, high}} range for {@code region}, or {@code null} when
505	     *  the region carries no range rule (i.e. {@code UNKNOWN} or any region absent from the table:
506	     *  {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
507	    public static int[] postcodeRangeForRegion(String region) {
508	        return REGION_POSTCODE_RANGES.get(region);
509	    }
510	
511	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
512	     *  absent, not a 4-digit value, or in no known range. */
513	    private static String regionForPostcode(String postcode) {
514	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
515	            return null;
516	        }
517	        int value = Integer.parseInt(postcode);
518	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
519	            int[] range = entry.getValue();
520	            if (value >= range[0] && value <= range[1]) {
521	                return entry.getKey();
522	            }
523	        }
524	        return null;
525	    }
526	
527	    /** Telephone country code -> the national-number length it requires ({@code +61} Australia => 9
528	     *  digits, {@code +1} NANP => 10), used to derive telephone values from the stored E.164 number.
529	     *  The country codes here carry no conflicting prefixes ({@code +61} does not start with
530	     *  {@code +1}), so a number matches at most one. */
531	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
532	        "+61", 9, "+1", 10);
533	
534	    /**
535	     * The stored E.164 {@link #telephone} formatted for humans, derived on read: the country code, a
536	     * space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}). Falls back
537	     * to the raw value when it is {@code null} or begins with no recognised country code.
538	     */
539	    @Transient
540	    public String getTelephoneDisplay() {
541	        if (this.telephone == null) {
542	            return null;
543	        }
544	        String countryCode = countryCodeOf(this.telephone);
545	        if (countryCode == null) {
546	            return this.telephone;
547	        }
548	        String national = this.telephone.substring(countryCode.length());
549	        StringBuilder grouped = new StringBuilder(countryCode);
550	        for (int i = 0; i < national.length(); i++) {
551	            if (i % 3 == 0) {
552	                grouped.append(' ');
553	            }
554	            grouped.append(national.charAt(i));
555	        }
556	        return grouped.toString();
557	    }
558	
559	    /** The recognised telephone country code that {@code telephone} begins with (e.g. {@code "+61"}),
560	     *  or {@code null} when it is {@code null} or begins with no recognised country code. */
561	    public static String countryCodeOf(String telephone) {
562	        if (telephone == null) {
563	            return null;
564	        }
565	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
566	            if (telephone.startsWith(countryCode)) {
567	                return countryCode;
568	            }
569	        }
570	        return null;
571	    }
572	
573	    /** The national-number length required for {@code countryCode}, or {@code null} when the country
574	     *  code carries no length rule (i.e. any code absent from the table: {@code +61 => 9},
575	     *  {@code +1 => 10}). */
576	    public static Integer nationalNumberLength(String countryCode) {
577	        return NATIONAL_NUMBER_LENGTHS.get(countryCode);
578	    }
579	
580	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
581	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
582	     *  digit-free value yields {@code 0}. */
583	    private static int luhnCheckDigit(String value) {
584	        int sum = 0;
585	        boolean doubling = true;
586	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
587	            char c = value.charAt(i);
588	            if (c < '0' || c > '9') {
589	                continue;
590	            }
591	            int digit = c - '0';
592	            if (doubling) {
593	                digit *= 2;
594	                if (digit > 9) {
595	                    digit -= 9;
596	                }
597	            }
598	            sum += digit;
599	            doubling = !doubling;
600	        }
601	        return (10 - (sum % 10)) % 10;
602	    }
603	
604	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters; the
605	     *  upper-case rendering of {@link #sha256HexLower(String)}. */
606	    public static String sha256Hex(String input) {
607	        return sha256HexLower(input).toUpperCase(Locale.ROOT);
608	    }
609	
610	    /** The lower-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
611	    public static String sha256HexLower(String input) {
612	        try {
613	            byte[] digest = MessageDigest.getInstance("SHA-256")
614	                .digest(input.getBytes(StandardCharsets.UTF_8));
615	            StringBuilder sb = new StringBuilder(digest.length * 2);
616	            for (byte b : digest) {
617	                sb.append(String.format("%02x", b));
618	            }
619	            return sb.toString();
620	        }
621	        catch (NoSuchAlgorithmException e) {
622	            throw new IllegalStateException("SHA-256 not available", e);
623	        }
624	    }
625	
626	    protected Set<Pet> getPetsInternal() {
627	        if (this.pets == null) {
628	            this.pets = new HashSet<>();
629	        }
630	        return this.pets;
631	    }
632	
633	    protected void setPetsInternal(Set<Pet> pets) {
634	        this.pets = pets;
635	    }
636	
637	    public List<Pet> getPets() {
638	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
639	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
640	        return Collections.unmodifiableList(sortedPets);
641	    }
642	
643	    public void setPets(List<Pet> pets) {
644	        this.pets = new HashSet<>(pets);
645	    }
646	
647	    public void addPet(Pet pet) {
648	        getPetsInternal().add(pet);
649	        pet.setOwner(this);
650	    }
651	
652	    /**
653	     * Return the Pet with the given name, or null if none found for this Owner.
654	     *
655	     * @param name to test
656	     * @return true if pet name is already in use
657	     */
658	    public Pet getPet(String name) {
659	        return getPet(name, false);
660	    }
661	
662	    /**
663	     * Return the Pet with the given name, or null if none found for this Owner.
664	     *
665	     * @param name to test
666	     * @return true if pet name is already in use
667	     */
668	    public Pet getPet(String name, boolean ignoreNew) {
669	        name = name.toLowerCase();
670	        for (Pet pet : getPetsInternal()) {
671	            if (!ignoreNew || !pet.isNew()) {
672	                String compName = pet.getName();
673	                compName = compName.toLowerCase();
674	                if (compName.equals(name)) {
675	                    return pet;
676	                }
677	            }
678	        }
679	        return null;
680	    }
681	
682	    public Pet getPet(Integer petId) {
683	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
684	    }
685	
686	    @Override
687	    public String toString() {
688	        return new ToStringCreator(this)
689	
690	            .append("id", this.getId())
691	            .append("new", this.isNew())
692	            .append("lastName", this.getLastName())
693	            .append("firstName", this.getFirstName())
694	            .append("address", this.address)
695	            .append("city", this.city)
696	            .append("telephone", this.telephone)
697	            .toString();
698	    }
699	}
